import numpy as np


def l2_penalty(weights, lam):
    return lam * sum(np.sum(w ** 2) for w in weights)


def dropout(x, p, rng, training=True):
    if not training or p == 0:
        return x
    mask = rng.random(x.shape) >= p
    return x * mask / (1 - p)


def early_stopping(val_losses, patience=3):
    best_epoch, best_loss, waited = 0, float("inf"), 0
    for epoch, loss in enumerate(val_losses):
        if loss < best_loss:
            best_epoch, best_loss, waited = epoch, loss, 0
        else:
            waited += 1
            if waited == patience:
                return epoch, best_epoch
    return len(val_losses) - 1, best_epoch


weights = [np.array([[0.5, -1.0], [2.0, 0.0]]), np.array([1.0, -0.5])]
print("L2 penalty (lambda=0.01):", l2_penalty(weights, 0.01))

rng = np.random.default_rng(0)
activations = np.ones(8)
print("dropout (training):", dropout(activations, 0.5, rng, training=True))
print("dropout (evaluation):", dropout(activations, 0.5, rng, training=False))

val_losses = [1.0, 0.8, 0.7, 0.72, 0.75, 0.71, 0.9, 0.95]
print("early stopping (stop epoch, best epoch):", early_stopping(val_losses, patience=3))
